// Top-level directories of the docs, in sidebar order, with human labels.
// Used for breadcrumbs and to group pages in /llms.txt.

// `pages` mirrors the manual sidebar order in astro.config.mjs; autogenerated sections
// are ordered by `sidebar.order`, then title.
export const SECTIONS: { dir: string; label: string; optional?: boolean; pages?: string[] }[] = [
	{
		dir: 'getting-started',
		label: 'Getting started',
		pages: ['introduction', 'quick-start', 'installation'],
	},
	{
		dir: 'integrate',
		label: 'Integrate',
		pages: ['overview', 'proxy-mode', 'gateway-mode', 'rust', 'docker-kubernetes', 'any-endpoint'],
	},
	{
		dir: 'concepts',
		label: 'Concepts',
		pages: ['how-it-works', 'personas', 'vault', 'detection', 'intent-policy', 'file-masking', 'tool-calls', 'activity-dashboard'],
	},
	{ dir: 'benchmarks', label: 'Benchmarks' },
	{ dir: 'compare', label: 'Compare' },
	{ dir: 'use-cases', label: 'Use cases' },
	{ dir: 'industries', label: 'Industries' },
	{ dir: 'company-size', label: 'Company size' },
	{
		dir: 'reference',
		label: 'Reference',
		pages: ['configuration', 'cli', 'providers', 'security', 'faq', 'troubleshooting'],
	},
	{ dir: 'project', label: 'Project', optional: true, pages: ['roadmap', 'contributing', 'changelog'] },
];

export function sectionLabel(dir: string): string {
	return (
		SECTIONS.find((s) => s.dir === dir)?.label ??
		dir.replace(/-/g, ' ').replace(/^./, (c) => c.toUpperCase())
	);
}

/** Collection id ('concepts/vault', 'compare/index', 'index') to URL slug ('concepts/vault', 'compare', ''). */
export function idToSlug(id: string): string {
	return id.replace(/(^|\/)index$/, '').replace(/\/$/, '');
}
